self.addEventListener("push",function(t){let n=JSON.parse(t.data.text()||"{}");t.waitUntil(self.registration.showNotification(n.title||"Th\xf4ng b\xe1o mới",{body:n.body||"Bạn c\xf3 nhiệm vụ mới tại trạm.",icon:n.icon||"/icon-192x192.png",badge:"/icon-192x192.png",data:n.url||"/pwr/station"}))}),self.addEventListener("notificationclick",function(t){t.notification.close(),t.waitUntil(clients.matchAll({type:"window",includeUncontrolled:!0}).then(function(n){if(n.length>0){let t=n[0];for(let i=0;i<n.length;i++)n[i].focused&&(t=n[i]);return t.focus()}return clients.openWindow(t.notification.data)}))});